/**  The user's Paparats Pro state. Pro is active when `plan != free` or a gift is running. */
export type Subscription = {
  plan: PlanId;
  /**  Next renewal of a paid plan. */
  renewsOn: string | null;
  /**  Pro granted as a thank-you for a released idea ("Paparats Pro · gift"), active until then. */
  giftUntil: string | null;
};

/**  Result of "Sync now". */
export type SyncOutcome = { kind: "synced"; at: string } | { kind: "unreachable"; days: number };

/**
 *  Text that is either translated by its author (catalog content) or written once in whatever
 *  language the user typed (user-generated ideas and comments).
 */
export type Text = Localized<string> | string;

export type ThemePreference = "light" | "dark" | "system";

/**  What the tray asks the UI to do (`shell://tray-action`). */
export type TrayAction =
  /**  "Check for updates": the UI opens Settings › About and checks for a new Paparats version. */
  "checkForUpdates";

/**  `shell://tray-action` — a tray menu entry the UI carries out ("Check for updates"). */
export type TrayActionEvent = TrayAction;

/**  How much Paparats vouches for a channel. Ordered from most to least trusted. */
export type TrustLevel =
  /**  The Paparats catalog: curated, tested and signed by Paparats. */
  | "official"
  /**  Author reviewed by Paparats; files mirrored by Paparats. */
  | "verified"
  /**  Anyone can publish; files come straight from the author's server. */
  | "community";

/**  Release notes and download size of the latest version of an app (the update manifest). */
export type UpdateManifest = {
  appId: string;
  /**  Size of the update download, in megabytes (may differ from the full install size). */
  downloadMb: number;
  notes: Localized<string[]>;
  /**
   *  The download manifest of the new version: install strategy, expected SHA-256 and signer.
   *  `None` (null or absent) in data sets that do not publish one; the mock world's are
   *  `simulated`.
   */
  package: Package | null;
};

export type UpdateSchedule = "hourly" | "daily" | "weekly";

/**  Personal usage numbers (Profile › Usage stats). */
export type UsageStats = {
  /**  Updates installed through Paparats over the account's lifetime. */
  updatesInstalled: number;
  timeSavedHours: number;
};

/* Tauri Specta runtime */
async function typedError<T, E>(
  result: Promise<T>,
): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
  try {
    return { status: "ok", data: await result };
  } catch (e) {
    if (e instanceof Error) throw e;
    return { status: "error", error: e as any };
  }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(
  name: string,
  serialize?: (payload: T) => unknown,
  deserialize?: (payload: any) => T,
) {
  const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) =>
    cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
  const mapPayload = (payload: T) => (serialize ? serialize(payload) : payload);

  const base = {
    listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
    once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
    emit: ((payload: T) =>
      __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>,
  };

  const fn = (
    target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window,
  ) => ({
    listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
    once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
    emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>,
  });

  return Object.assign(fn, base);
}
